public class BooleanOptionHandler_parseArguments_TriageGen0Test {

    private CommandLineParser mockParser;
    private OptionDef mockOptionDef;
    private Setter<Boolean> mockSetter;
    private Parameters mockParams;
    private BooleanOptionHandler handler;

    @Before
    public void setUp() {
        mockParser = mock(CommandLineParser.class);
        mockOptionDef = mock(OptionDef.class);
        mockSetter = mock(Setter.class);
        mockParams = mock(Parameters.class);
        handler = new BooleanOptionHandler(mockParser, mockOptionDef, mockSetter);
    }

    @Test
    public void testParseArguments_NullParam() throws Exception {
        when(mockParams.getParameter(0)).thenReturn(null);

        int result = handler.parseArguments(mockParams);

        assertEquals(0, result);
        verify(mockSetter).addValue(true);
    }

    @Test
    public void testParseArguments_TrueParam() throws Exception {
        // Assuming TRUES contains "true"
        when(mockParams.getParameter(0)).thenReturn("true");

        int result = handler.parseArguments(mockParams);

        assertEquals(1, result);
        verify(mockSetter).addValue(true);
    }

    @Test
    public void testParseArguments_TrueParamCaseInsensitive() throws Exception {
        // Assuming TRUES contains "true"
        when(mockParams.getParameter(0)).thenReturn("TRUE");

        int result = handler.parseArguments(mockParams);

        assertEquals(1, result);
        verify(mockSetter).addValue(true);
    }

    @Test
    public void testParseArguments_FalseParam() throws Exception {
        // Assuming FALSES contains "false"
        when(mockParams.getParameter(0)).thenReturn("false");

        int result = handler.parseArguments(mockParams);

        assertEquals(1, result);
        verify(mockSetter).addValue(false);
    }

    @Test
    public void testParseArguments_FalseParamCaseInsensitive() throws Exception {
        // Assuming FALSES contains "false"
        when(mockParams.getParameter(0)).thenReturn("fAlSe");

        int result = handler.parseArguments(mockParams);

        assertEquals(1, result);
        verify(mockSetter).addValue(false);
    }

    @Test
    public void testParseArguments_InvalidParam() throws Exception {
        when(mockParams.getParameter(0)).thenReturn("not_a_boolean");

        int result = handler.parseArguments(mockParams);

        assertEquals(0, result);
        verify(mockSetter).addValue(true);
    }
}
